      "煙による追い出し：ホームセンターや薬局などで市販されている、(火を使わずに)煙の出るタイプの害虫駆除剤を屋根裏に置いて追い出す。／忌避剤による追い出し：コウモリが住み着いている場所の近くにナフタリン等の固形忌避剤を置いたり、スプレータイプの忌避剤を噴射する等により追い出す。／ネット等による侵入防止：侵入口や住み着いている場所にコウモリがいない時に（または追い払ってから）、その場所にネット(網)やパテ、シーリング材等ですき間をふさぐようにして侵入を防ぐ。※高所である場合には危険ですので、専門業者への依頼についてもご検討ください。（茨城県つくばみらい市 生活環境課）",
