      "東京消防庁のまとめによると、同庁管内では毎年約6,000から7,000件の火災が発生しており、そのうちねずみが原因であることが確認された火災は毎年12件ほど発生している。平成8年から15年の間に起ったねずみに起因する火災の総件数は97件で… 火災による直接的な損害額は、年間約5,000万円に上っている。（東京都保健医療局「東京都ねずみ防除指針」Ⅲ-2 都市機能の阻害（火災関係））",
      "ねずみによる具体的被害の内容は」という問いに対し、「糞が散乱して不衛生」（88人）、「食品や家具を齧られた」（9人）といった物理的な被害以外に、「夜に眠れないことで、体力が低下し持病が悪化した（8人）」、「夜に眠れないことで、日中に寝てしまい、食事や服薬、デイケアなどのケア体制がうまく遂行できない」（14人）、「不安、気持ち悪い」（9人）のように、精神面での被害も多く挙げられた。（東京都保健医療局「東京都ねずみ防除指針」Ⅲ-1(3) 精神的被害（高齢者宅におけるねずみ被害の実態調査））",
